INSERT INTO public.vector_store (id,"content",metadata,embedding) VALUES
	 ('228912f4-c322-4b4c-8863-15963748bd79'::uuid,'Mira was one of two female tributes from District 12 who participated in the 50th Hunger Games. During the chariot rides, the chariot carrying District 12 narrowly missed colliding with another district. Before the start of the games, Mira and her district joined an alliance between several district tributes in an attempt to counter the Career pack. Her token was a horseshoe. She died in the initial bloodbath with the other girl from her district. Mira, along with the other three tributes from District 12, wore a specific outfit during the chariot rides.','{"source": "Peeler.txt", "charset": "UTF-8", "chunk_id": 0, "position": 0, "chunk_index": 0, "total_chunks": 1, "source_document": "/Users/artem/IdeaProjects/practicum/sprint07/ragbot/./data/replaced/Peeler.txt", "parent_document_id": "ccc5431c-1067-4bb4-aa19-1599a1a1070e"}','[0.06033079,0.06358957,-0.02640607,-0.010993191,0.0024912143,-0.0142418835,0.046623077,-0.016243096,-0.07636491,0.059008595,-0.018415172,-0.06995904,0.056728166,-0.019353628,0.0074853953,-0.03802191,-0.014569811,0.02308044,-0.021364475,0.064214766,-0.0021981033,0.020397779,0.016314905,-0.06265638,0.005158636,-0.0068174386,0.02627046,-0.011155874,-0.08286099,0.012935342,-0.011918198,0.009351277,0.000262576,0.022006065,-0.00018591528,0.009211839,0.008535428,0.00123791,-0.00023565596,-0.047184866,0.0078409,-0.002166204,0.004739281,-0.0013389271,0.0053229355,0.020171776,0.043969348,-0.016794778,0.00046229968,-0.026342813,0.024987925,-0.03809879,-0.019910723,0.01861453,0.037682597,0.017408768,-0.0144610405,0.018853672,-0.045626227,-0.017728828,-0.01428063,0.001411055,0.035073496,0.04481612,-0.004741517,-0.04398559,-0.025765333,-0.006469128,0.023130972,0.013222459,0.01813161,-0.0016806046,0.006746315,-0.005904566,-0.0016500353,-0.029304225,-0.054436702,-0.035717417,0.013446249,0.0041871257,-0.023447176,0.004580066,-0.03668021,-0.0154721765,0.0164336,-0.036785908,-0.029124431,-1.9793497e-06,-0.0058197