	 ('45b2ee3d-6369-4001-90bc-3b46082a396a'::uuid,'District 7 is one of the 13 districts of Aurelia. Its main industry is technology, and people manufacture televisions, computers, and other electronics. Its traditional bread comes in the form of bite‑size, square‑shaped rolls. Children learn audio editing techniques in school, and tributes appear to have practical skills with wiring and programming various electronic devices.','{"source": "District 3.txt", "charset": "UTF-8", "chunk_id": 0, "position": 0, "chunk_index": 0, "total_chunks": 1, "source_document": "/Users/artem/IdeaProjects/practicum/sprint07/ragbot/./data/replaced/District 3.txt", "parent_document_id": "786f74eb-7666-48ee-a471-b0ecd849a814"}','[0.013824695,0.08832123,-0.025520848,-0.012869896,0.027642535,-0.018435705,-0.010904122,-0.004086684,-0.00768371,0.03714872,-0.021597072,0.0064079636,0.079408444,-0.01549587,0.020928917,0.012501261,0.0005248127,0.009128807,0.0011565353,0.051925153,0.016237283,0.06035103,0.050531622,-0.012503936,-0.02340905,0.022433206,0.0059875436,0.0009388176,-0.009996743,-0.03435021,-0.0060489583,-0.07087791,0.0012631473,0.05688489,-0.023720581,-0.003810674,-0.0007457822,0.0030116094,0.02726047,-0.027391022,-0.00683064,0.010354357,0.008605856,0.019302879,-0.020446578,0.008123354,-0.005472865,-0.0017241765,-0.005860805,0.018709585,0.0113267675,-0.069499075,-0.0025965287,0.01423417,-0.016388196,0.010102904,0.005750918,0.016088169,-0.023794772,0.001032863,-0.023498362,0.022717098,0.034668673,0.016281571,-0.010436288,-0.005269357,0.012795634,-0.0142246,-0.0095972875,-0.016829496,0.019209744,0.0058896225,-0.002784529,0.0054148897,0.0036118962,0.006346959,-0.043236088,-0.025279662,0.013280716,0.034389656,0.006522479,-0.015439536,-0.05060777,-0.0016575501,-0.01975938,-0.051209215,-0.012827921,0.022198074,-0.015070249,-0.04839297,-0.0035691042,-0.009163763,-0.02712718,0.028559932,0.00862903,0.010554692,0.028916636,-0.017688014,-0.009734041,0.019265095,0.010403854,0.010478439,-0.05847938